    private static float[][] Rows(int width, params float[] flat)
    {
        var table = new float[flat.Length / width][];
        for (int i = 0; i < table.Length; i++)
        {
            table[i] = new float[width];
            System.Array.Copy(flat, i * width, table[i], 0, width);
        }

        return table;
    }
